 * Vercel Functions entry point for the Effect HTTP API.
 *
 * Exports a web-standard fetch handler that Vercel invokes for each request.
 * tsdown bundles this file (and all workspace dependencies) into `api/index.js`
 * so that Vercel can run it as a serverless function.
 *
 * Uses `waitUntil` to extend function lifetime so batched OTLP telemetry
 * (traces, logs, metrics) has time to flush before Vercel terminates the function.
 *
 * @see https://github.com/IMax153/vercel-functions-test
 */

import { makeHttpApiLive } from "@backend/http-api/live";
import { makeHttpApiServer } from "@backend/http-api/server";
import { makeServerObservabilityLive } from "@backend/tracing/observability";
import { InstrumentedRuntimeBridgeLive } from "@mobius/jobs/runtime";
import { waitUntil } from "@vercel/functions";
import { Layer } from "effect";
import { ObservabilityPlatformLive } from "./observability-platform.js";

// Vercel reuses module scope across warm invocations. Keep one memo map for the
// handler scope, then dispose it on shutdown so scoped exporters can flush.
const memoMap = Layer.makeMemoMapUnsafe();
const ObservabilityLive = makeServerObservabilityLive("mobius-api").pipe(
  Layer.provide(ObservabilityPlatformLive)
);
const RuntimeBridgeLive = InstrumentedRuntimeBridgeLive.pipe(
  Layer.provide(ObservabilityPlatformLive)
);

const ApiLive = Layer.merge(
  makeHttpApiLive(ObservabilityLive),
  RuntimeBridgeLive.pipe(Layer.provide(ObservabilityLive))
);
const { dispose, handler } = makeHttpApiServer(ApiLive, { memoMap });

const disposeRuntime = async () => {
  await dispose();
};

process.once("SIGTERM", () => {
  // Extend function lifetime so the OTLP BatchSpanProcessor can flush
  // remaining spans, logs, and metrics before Vercel sends SIGKILL (~10s grace).
  // dispose() triggers shutdownTimeout (3s) on the exporter — well within budget.
  waitUntil(disposeRuntime());
});

const fetch = async (request: Request): Promise<Response> => {
  const response = await handler(request);
  waitUntil(new Promise((resolve) => setTimeout(resolve, 1000)));
  return response;
};

export default { fetch };

