const servePublicAsset = async (pathname: string, method: string) => {
  if (method !== "GET" && method !== "HEAD") {
    return HttpServerResponse.text("Not Found", { status: 404 });
  }

  const normalizedPath = pathname === "/" ? "/index.html" : pathname;
  if (normalizedPath.includes("..")) {
    return HttpServerResponse.text("Not Found", { status: 404 });
  }

  // biome-ignore lint/correctness/noUndeclaredVariables: Bun global is provided by bun-types at runtime
  const file = Bun.file(new URL(`.${normalizedPath}`, publicDir));
  const exists = await file.exists();
  if (!exists) {
    return HttpServerResponse.text("Not Found", { status: 404 });
  }

  const extension = extname(normalizedPath).toLowerCase();
  const contentType =
    contentTypeByExtension[extension] ?? "application/octet-stream";
  const headers = { "Content-Type": contentType };

  if (method === "HEAD") {
    return HttpServerResponse.empty({ headers, status: 200 });
  }

  return HttpServerResponse.raw(file, { headers, status: 200 });
};

